@import "@fontsource-variable/public-sans";

/* Light (faithful): white page, #f3f3f3 hero band, warm-black ink #1e1e1c with warm-grey
   #53524b secondary text, deep teal #206d69 for actions, three pastel card tints
   (blue-grey, sage on accent / secondary; a mid sand highlight that blocks use at 30%, giving #ebe6d9). */
:root {
  --background: #ffffff;
  --foreground: #1e1e1c;
  --card: #ffffff;
  --card-foreground: #1e1e1c;
  --popover: #ffffff;
  --popover-foreground: #1e1e1c;
  --primary: #206d69;
  --primary-foreground: #fafaf9;
  --secondary: #dee8d9;
  --secondary-foreground: #1e1e1c;
  --muted: #f3f3f3;
  --muted-foreground: #53524b;
  --accent: #cbd9e3;
  --accent-foreground: #1e1e1c;
  --destructive: #c2412d;
  --destructive-foreground: #ffffff;
  --border: #eaeae8;
  --input: rgb(30 30 28 / 20%);
  --ring: #11a080;
  --highlight: #b9aa82;
  --highlight-foreground: #1e1e1c;
  --glow: #86e0b2;
  --chart-1: #206d69;
  --chart-2: #b08a55;
  --chart-3: #5b8ed1;
  --chart-4: #86e0b2;
  --chart-5: #53524b;
  --sidebar: #f3f3f3;
  --sidebar-foreground: #1e1e1c;
  --sidebar-primary: #206d69;
  --sidebar-primary-foreground: #fafaf9;
  --sidebar-accent: #ebebea;
  --sidebar-accent-foreground: #1e1e1c;
  --sidebar-border: #eaeae8;
  --sidebar-ring: #11a080;

  --typeface-body: "Public Sans Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-display: "Public Sans Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-mono: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  --radius: 0.5rem;
  --page-width: 73.75rem;
  --page-gutter: 1.25rem;
  /* 60px on phones growing to 120px on desktop, as the original's section gaps do */
  --section-y: clamp(3.75rem, 2.2rem + 6.4vw, 7.5rem);
}

/* Dark sibling: the original's #1e1e1c closing band as the page, its #262d2f slate panel as
   cards, the #222 testimonial band as muted, mint #86e0b2 for actions, deep pastel tints. */
.dark {
  --background: #1e1e1c;
  --foreground: #fafaf9;
  --card: #262d2f;
  --card-foreground: #fafaf9;
  --popover: #262d2f;
  --popover-foreground: #fafaf9;
  --primary: #86e0b2;
  --primary-foreground: #1e1e1c;
  --secondary: #2c352e;
  --secondary-foreground: #fafaf9;
  --muted: #222222;
  --muted-foreground: #c4c4bf;
  --accent: #2b353c;
  --accent-foreground: #fafaf9;
  --destructive: #e86a55;
  --destructive-foreground: #ffffff;
  --border: rgb(255 255 255 / 10%);
  --input: rgb(255 255 255 / 20%);
  --ring: #86e0b2;
  --highlight: #75674e;
  --highlight-foreground: #fafaf9;
  --glow: #86e0b2;
  --chart-1: #86e0b2;
  --chart-2: #d1ad78;
  --chart-3: #7fa9e0;
  --chart-4: #3fb8a0;
  --chart-5: #c4c4bf;
  --sidebar: #222222;
  --sidebar-foreground: #fafaf9;
  --sidebar-primary: #86e0b2;
  --sidebar-primary-foreground: #1e1e1c;
  --sidebar-accent: #2c2c2a;
  --sidebar-accent-foreground: #fafaf9;
  --sidebar-border: rgb(255 255 255 / 10%);
  --sidebar-ring: #86e0b2;
}
